        float newvalue;
        float x = currentFrame[pixel];

        newvalue = -((logf(x) - median[pixel]) - MeanLogNormalFrame[pixel]) / (sqrtf(2) * stdvLogNormalFrame[pixel]);

        float summ = 0.5f + 0.5f * erff(newvalue);

        if (summ >= 0.3) {
