    int ty = threadIdx.y + blockDim.y * blockIdx.y;
    float cutoff = 0.5;

    if ((tx < n_nodes_1) && (ty < n_nodes_2)) {
        int ind = tx * n_nodes_2 + ty;

        if ((node_info1[tx] < cutoff) && (node_info2[ty] < cutoff))
