__global__ void Backwardsub(double* U, double* RES, double* UN, double* UE, double* LPR, int NI, int NJ, int End, int J, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < n) {
        int IJ = ((End - i) * NI) + (J - (End - i));
        RES[IJ] = RES[IJ] - UN[IJ] * RES[IJ + 1] - UE[IJ] * RES[IJ + NJ];
        U[IJ] = U[IJ] + RES[IJ];
    }
}

__global__ void convolution_gpu_1d_naive(float* input, float* mask, float* output, int array_size, int mask_size) {
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    int MASK_RADIUS = mask_size / 2;
    int ELEMENT_INDEX = 0;
    float temp = 0.0f;

    if (gid < array_size) {
        for (int j = 0; j < mask_size; j++) {
            ELEMENT_INDEX = gid - MASK_RADIUS + j;
            if (!(ELEMENT_INDEX < 0 || ELEMENT_INDEX > (array_size - 1))) {
                temp += input[ELEMENT_INDEX] * mask[j];
            }
        }

        output[gid] = temp;
    }
}

__global__ void colLog2SumExp2Kernel(const double* mat, double* buf, int m, int n) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;

    if (j < n) {
        double maximum = mat[j];

        for (int i = 1; i < m; i++) {
            if (mat[i * n + j] > maximum) {
                maximum = mat[i * n + j];
            }
        }

        double res = 0.0;

        for (int i = 0; i < m; i++) {
            res += mat[i * n + j] - maximum;
        }

        buf[j] = res + maximum;
    }
}

__global__ void residual(double* out, double* x, double* b, double* cotans, int* neighbors, double* diag, int meshStride, int n) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    for (int i = index; i < n; i += stride) {
        out[i] = diag[i] * x[i] - b[i];

        for (int iN = 0; iN < meshStride; ++iN) {
            int neighbor = neighbors[i * meshStride + iN];
            double weight = cotans[i * meshStride + iN];
            out[i] -= weight * x[neighbor];
        }
    }
}

__global__ void forward_avgpool_layer_kernel(int n, int w, int h, int c, float* input, float* output) {
    int id = (blockIdx.x + blockIdx.y * gridDim.x) * blockDim.x + threadIdx.x;

    if (id >= n)
        return;

    int k = id % c;
    id /= c;
    int b = id;

    int i;
    int out_index = (k + c * b);
    output[out_index] = 0;

    for (i = 0; i < w * h; ++i) {
        int in_index = i + h * w * (k + b * c);
        output[out_index] += input[in_index];
    }

    output[out_index] /= w * h;
}

__global__ void kernel_columns(const float* filter, const float* buffer, float* output, int imageW, int imageH, int filterR) {
    int idx_x = threadIdx.x + blockDim.x * blockIdx.x;
    int idx_y = threadIdx.y + blockDim.y * blockIdx.y;
    int grid_width = gridDim.x * blockDim.x;
    int idx = grid_width * idx_y + idx_x;

    float sum = 0;

    for (int k = -filterR; k <= filterR; k++) {
        int d = idx_y + k;

        if (d >= 0 && d < imageH) {
            sum += buffer[d * imageW + idx_x] * filter[filterR - k];
        }
    }

    output[idx] = sum;
}

