__global__ void variance_kernel(float* x, float* mean, int batch, int filters, int spatial, float* variance) {
    float scale = 1.f / (batch * spatial - 1);
    int j, k;
    int i = (blockIdx.x + blockIdx.y * gridDim.x) * blockDim.x + threadIdx.x;

    if (i >= filters)
        return;

    variance[i] = 0;

    for (j = 0; j < batch; ++j) {
        for (k = 0; k < spatial; ++k) {
            int index = j * filters * spatial + i * spatial + k;
            variance[i] += powf((x[index] - mean[i]), 2);
        }
    }

    variance[i] *= scale;
}

__global__ void grad_y(const float* u, float* grad, long depth, long rows, long cols) {
    unsigned long x = threadIdx.x + blockIdx.x * blockDim.x;
    unsigned long y = threadIdx.y + blockIdx.y * blockDim.y;
    unsigned long z = threadIdx.z + blockIdx.z * blockDim.z;

    if (x >= cols || y >= rows || z >= depth)
        return;

    unsigned long size2d = rows * cols;
    unsigned long long idx = z * size2d + y * cols + x;
    float uidx = u[idx];

    if (y - 1 >= 0 && y < rows) {
        grad[idx] = (uidx - u[z * size2d + (y - 1) * cols + x]);
    }
}

__global__ void cuda_GraphSum_forward_kernel(float* d_in_data, float* d_out_data, int* d_indptr, int* d_indices, int dim, int numNodes) {
    int src = blockIdx.x;
    int j = threadIdx.x;
    int ptr_src_0 = d_indptr[src];
    int ptr_stc_1 = d_indptr[src + 1];

    for (int i = ptr_src_0; i < ptr_stc_1; i++) {
        int dst = d_indices[i];
        float coef = 1.0 / sqrtf((ptr_stc_1 - ptr_src_0) * (d_indptr[dst + 1] - d_indptr[dst]));
        d_out_data[src * dim + j] += coef * d_in_data[dst * dim + j];
    }
}

__global__ void cuda_GraphSum_backward_kernel(float* d_in_grad, float* d_out_grad, int* d_indptr, int* d_indices, int dim, int numNodes) {
    int src = blockIdx.x;
    int j = threadIdx.x;
    int ptr_src_0 = d_indptr[src];
    int ptr_stc_1 = d_indptr[src + 1];

    #pragma unroll
    for (int i = ptr_src_0; i < ptr_stc_1; i++) {
        int dst = d_indices[i];
        float coef = 1.0 / sqrtf((ptr_stc_1 - ptr_src_0) * (d_indptr[dst + 1] - d_indptr[dst]));

        d_in_grad[src * dim + j] += coef * d_out_grad[dst * dim + j];
    }
}

__global__ void normalizacion(float* image_c, int bands, long int image_size, float* normM_c, float* normM1_c) {
    long int j, i;
    float norm_val = 0, aux = 0, pixel = 0;

    i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < image_size) {
        for (j = 0; j < bands; j++) {
            norm_val += image_c[j * image_size + i];
        }

        norm_val = 1.0 / (norm_val + 1.0e-16);

        for (j = 0; j < bands; j++) {
            pixel = image_c[j * image_size + i] * norm_val;
            image_c[j * image_size + i] = pixel;
            aux += pixel * pixel;
        }

        normM_c[i] = aux;
        normM1_c[i] = aux;
    }
}

__global__ void cudaSimpleCorrelator(float* xi, float* xq, float* sr, float* si, int sLength, float* L, int uLength) {
    int u = (blockIdx.x * blockDim.x) + threadIdx.x;

    if (u >= uLength)
        return;

    float real = 0;
    float imag = 0;
    float a, b, c, d;

    for (int n = u; n < u + sLength; n++) {
        a = xi[n];
        b = xq[n];
        c = sr[n - u];
        d = si[n - u] * (-1);

        real += (a * c) - (b * d);
        imag += (a * d) + (b * c);
    }

    L[u] = sqrt(real * real + imag * imag);
}

__global__ void runFilterCuda(float* I, float* Q, int samplesLength, float* filter, int filterLength,
                               float* filtered_I, float* filtered_Q, int convLength) {
    int sampleIndex = (blockIdx.x * blockDim.x) + threadIdx.x;

    if (sampleIndex >= convLength)
        return;

    int index;
    float sumI, sumQ;

    sumI = 0;
    sumQ = 0;

    for (int j = sampleIndex - filterLength + 1; j <= sampleIndex; j++) {
        index = sampleIndex - j;

        if ((j < samplesLength) && (j >= 0)) {
            sumI += filter[index] * I[j];
            sumQ += filter[index] * Q[j];
        }
    }

    filtered_I[sampleIndex] = sumI;
    filtered_Q[sampleIndex] = sumQ;
}

__global__ void l2normalize_kernel(int N, float* x, float* dx, int batch, int filters, int spatial) {
    int index = (blockIdx.x + blockIdx.y * gridDim.x) * blockDim.x + threadIdx.x;

    if (index >= N)
        return;

    int b = index / spatial;
    int i = index % spatial;
    int f;
    float sum = 0;

    for (f = 0; f < filters; ++f) {
        int index = b * filters * spatial + f * spatial + i;
        sum += powf(x[index], 2);
    }

    sum = sqrtf(sum);

    if (sum == 0)
        sum = 1;

    for (f = 0; f < filters; ++f) {
        int index = b * filters * spatial + f * spatial + i;
        x[index] /= sum;
        dx[index] = (1 - x[index]) / sum;
    }
}

__global__ void distanceMatCalc(long int totalPixels, int availablePixels, int outPixelOffset, int patchSize, float* distMat, float* data, float filtSig) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (long int i = index; i < availablePixels * totalPixels; i += stride) {
        int data_i = i / totalPixels + outPixelOffset;
        int data_j = i % totalPixels;
        float tmp = 0.0;

        if (data_i != data_j) {
            for (int elem = 0; elem < patchSize * patchSize; elem++) {
                float diff = (data[data_i * patchSize * patchSize + elem] - data[data_j * patchSize * patchSize + elem]);
                tmp += diff * diff;
            }

            tmp = exp(-tmp / filtSig);
        }

        distMat[i] = tmp;
    }
}

__global__ void ConvLayerForward_Kernel(int C, int W_grid, int K, float *X, float *W, float *Y) {
    int n, m, h, w, c, p, q;
    
    n = blockIdx.x;
    m = blockIdx.y;
    h = blockIdx.z / W_grid + threadIdx.y;
    w = blockIdx.z % W_grid + threadIdx.x;

    float acc = 0;

    for (c = 0; c < C; c++) {
        for (p = 0; p < K; p++) {
            for (q = 0; q < K; q++) {
                acc += X[n * C * W_grid * W_grid + c * W_grid * W_grid + (h + p) * W_grid + (w + q)] * W[m * C * K * K + c * K * K + p * K + q];
            }
        }
    }

    Y[n * W_grid * W_grid * W_grid + m * W_grid * W_grid + h * W_grid + w] = acc;
}

__global__ void opL23(float *vec, float *vec1, long depth, long rows, long cols) {
    unsigned long x = threadIdx.x + blockIdx.x * blockDim.x;
    unsigned long y = threadIdx.y + blockIdx.y * blockDim.y;
    unsigned long z = threadIdx.z + blockIdx.z * blockDim.z;
    unsigned long long i = z * rows * cols + y * cols + x;
    unsigned long long j = z * rows * cols + y * cols;
    unsigned long size2d = cols;
    unsigned long size3d = depth * rows * cols + rows * cols + cols;

    if (x >= cols || y >= rows || z >= depth)
        return;

    if (i + cols + 1 >= size3d)
        return;

    vec[i + cols] = 0.5 * (vec1[i + cols] + vec1[i]);

    if (j + 1 >= size2d)
        return;

    vec[j] = 0.5 * (vec1[j]);
}

__global__ void opL12(float *vec, float *vec1, long depth, long rows, long cols) {
    unsigned long x = threadIdx.x + blockIdx.x * blockDim.x;
    unsigned long y = threadIdx.y + blockIdx.y * blockDim.y;
    unsigned long z = threadIdx.z + blockIdx.z * blockDim.z;
    unsigned long long i = z * rows * cols + y * cols + x;
    unsigned long long j = z * rows * cols + y * cols;
    unsigned long size2d = cols;
    unsigned long size3d = depth * rows * cols + rows * cols + cols;

    if (x >= cols || y >= rows || z >= depth)
        return;

    if (i + cols + 1 >= size3d)
        return;

    vec[i + 1] = 0.25 * (vec1[i + 1] + vec1[i] + vec1[i + cols + 1] + vec1[i + cols]);

    if (j + 1 >= size2d)
        return;

    vec[j] = 0.25 * (vec1[j] + vec1[j + cols]);
}

__global__ void cudaBYUSimplified(float *xi, float *xq, float *sr, float *si, int N, int Lq, float *L) {
    int u = (blockIdx.x * blockDim.x) + threadIdx.x;

    if (u >= N)
        return;

    float uSum = 0;
    float r_i, r_q, q_i, q_q;
    float realPart, imagPart;

    for (int k = 0; k <= 7; k++) {
        realPart = 0;
        imagPart = 0;

        for (int l = 0; l < Lq; l++) {
            r_i = xi[u + k * Lq + l];
            r_q = xq[u + k * Lq + l];
            q_i = sr[l];
            q_q = si[l] * (-1);

            realPart += (r_i * q_i) - (r_q * q_q);
            imagPart += (r_i * q_q) + (r_q * q_i);
        }

        uSum += (realPart * realPart) + (imagPart * imagPart);
    }

    L[u] = uSum;
}

__global__ void fractal(const int width, const int frames, unsigned char *const pic) {
    const long i = threadIdx.x + blockIdx.x * (long)blockDim.x;

    if (i > width * width * frames) {
        return;
    }

    const float Delta = 0.00304f;
    const float xMid = -0.055846456f;
    const float yMid = -0.668311119f;

    const int frame = i / (width * width);
    float delta = Delta * powf(0.975f, frame);

    const int col = i % width;
    const float xMin = xMid - delta;
    const float yMin = yMid - delta;

    const float dw = 2.0f * delta / width;
    const int row = (i / width) % width;

    const float cy = yMin + row * dw;
    const float cx = xMin + col * dw;

    float x = cx;
    float y = cy;
    float x2, y2;
    int count = 256;

    do {
        x2 = x * x;
        y2 = y * y;
        y = 2.0 * x * y + cy;
        x = x2 - y2 + cx;
        count--;
    } while ((count > 0) && ((x2 + y2) <= 5.0));

    pic[frame * width * width + row * width + col] = (unsigned char)count;
}

__global__ void Match(float *P, float *Q, int q_points, int *idx) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    float min = 100000;
    float d;
    float xp = P[0 + i * 3];
    float yp = P[1 + i * 3];
    float zp = P[2 + i * 3];
    float xq, yq, zq;
    int j;

    for (j = 0; j < q_points / 2; j++) {
        xq = Q[0 + j * 3];
        yq = Q[1 + j * 3];
        zq = Q[2 + j * 3];
        d = (xp - xq) * (xp - xq) + (yp - yq) * (yp - yq) + (zp - zq) * (zp - zq);
        if (d < min) {
            min = d;
            idx[i] = j;
        }
    }

    for (j = j; j < q_points; j++) {
        xq = Q[0 + j * 3];
        yq = Q[1 + j * 3];
        zq = Q[2 + j * 3];
        d = (xp - xq) * (xp - xq) + (yp - yq) * (yp - yq) + (zp - zq) * (zp - zq);
        if (d < min) {
            min = d;
            idx[i] = j;
        }
    }
}

__global__ void col2im_gpu_kernel(const int n, const float *data_col, const int height, const int width, const int ksize,
                                  const int pad, const int stride, const int height_col, const int width_col,
                                  float *data_im) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;

    for (; index < n; index += blockDim.x * gridDim.x) {
        float val = 0;
        int w = index % width + pad;
        int h = (index / width) % height + pad;
        int c = index / (width * height);
        int w_col_start = (w < ksize) ? 0 : (w - ksize) / stride + 1;
        int w_col_end = min(w / stride + 1, width_col);
        int h_col_start = (h < ksize) ? 0 : (h - ksize) / stride + 1;
        int h_col_end = min(h / stride + 1, height_col);
        int offset = (c * ksize * ksize + h * ksize + w) * height_col * width_col;
        int coeff_h_col = (1 - stride * ksize * height_col) * width_col;
        int coeff_w_col = (1 - stride * height_col * width_col);

        for (int h_col = h_col_start; h_col < h_col_end; ++h_col) {
            for (int w_col = w_col_start; w_col < w_col_end; ++w_col) {
                val += data_col[offset + h_col * coeff_h_col + w_col * coeff_w_col];
            }
        }

        data_im[index] += val;
    }
}

__global__ void eltwise_kernel(int size, int minw, int minh, int minc, int stride, int sample, int batch,
                               int w1, int h1, int c1, float *add, int w2, int h2, int c2, float *out,
                               int sum, int mult) {
    int id = (blockIdx.x + blockIdx.y * gridDim.x) * blockDim.x + threadIdx.x;

    if (id >= size) {
        return;
    }

    int i = id % minw;
    id /= minw;
    int j = id % minh;
    id /= minh;
    int k = id % minc;
    id /= minc;
    int b = id % batch;

    int out_index = i * sample + w2 * (j * sample + h2 * (k + c2 * b));
    int add_index = i * stride + w1 * (j * stride + h1 * (k + c1 * b));

    if (mult == 1)
        out[out_index] = out[out_index] * add[add_index];
    else if (sum == 1)
        out[out_index] = out[out_index] + add[add_index];
}

__global__ void nlf_filter_left_backward(const int n, const float *bottom_data, const float *top_data,
                                          const float *temp_diff, const int channel,
                                          const int height, const int width, const int wsize,
                                          float *filters_diff) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;

    if (index >= n) {
        return;
    }

    int step = height * width;
    int base = index / step * step * channel + index % step;
    int fbase = index / step * step * wsize + index % step;
    int row = index % step / width;
    int col = index % step % width;

    for (int i = 0; i < channel; i++) {
        filters_diff[fbase] += temp_diff[base + i * step] * bottom_data[base + i * step];

        if (col + 1 < width)
            filters_diff[fbase + step] += temp_diff[base + i * step] * top_data[base + 1 + i * step];
        else
            filters_diff[fbase + step] += temp_diff[base + i * step] * bottom_data[base + i * step];

        if (col + 1 < width && row - 1 >= 0)
            filters_diff[fbase + 2 * step] +=
                temp_diff[base + i * step] * top_data[base - width + 1 + i * step];
        else
            filters_diff[fbase + 2 * step] += temp_diff[base + i * step] * bottom_data[base + i * step];

        if (col + 1 < width && row + 1 < height)
            filters_diff[fbase + 3 * step] +=
                temp_diff[base + i * step] * top_data[base + width + 1 + i * step];
        else
            filters_diff[fbase + 3 * step] += temp_diff[base + i * step] * bottom_data[base + i * step];

        if (row + 1 < height)
            filters_diff[fbase + 4 * step] += temp_diff[base + i * step] * top_data[base + width + i * step];
        else
            filters_diff[fbase + 4 * step] += temp_diff[base + i * step] * bottom_data[base + i * step];
    }
}

