    float temp1 = 0., temp2 = 0.;
    for (int j = 0; j < c; j++)
        temp1 = fmaxf(x[i * c + j], temp1);

    for (int j = 0; j < c; j++) {
        x[i * c + j] = expf(x[i * c + j] - temp1);
        temp2 += x[i * c + j];
    }

    for (int j = 0; j < c; j++)
