__global__ void cuda_laplace_filter(float *Img, float *laplace, float _dz, float _dx, int npml, int nnz, int nnx) {
    int i1 = threadIdx.x + blockDim.x * blockIdx.x;
    int i2 = threadIdx.y + blockDim.y * blockIdx.y;
    int id = i1 + i2 * nnz;
    float diff1 = 0.0f;
    float diff2 = 0.0f;

    if (i1 >= npml && i1 < nnz - npml && i2 >= npml && i2 < nnx - npml) {
        diff1 = Img[id + 1] - 2.0 * Img[id] + Img[id - 1];
        diff2 = Img[id + nnz] - 2.0 * Img[id] + Img[id - nnz];
    }

    laplace[id] = _dz * _dz * diff1 + _dx * _dx * diff2;
}

__global__ void distanceMatFinal(long int totalPixels, int availablePixels, int outPixelOffset, float *distMat) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (long int i = index; i < availablePixels; i += stride) {
        float sum = 0.0;
        float max = 0.0;

        for (long int j = 0; j < totalPixels; j++) {
            float element = distMat[i * totalPixels + j];
            if (element > max) max = element;
            sum += element;
        }

        sum += max;

        for (long int j = 0; j < totalPixels; j++) {
            if ((i + outPixelOffset) == j)
                distMat[i * totalPixels + j] = max / sum;
            else
                distMat[i * totalPixels + j] /= sum;
        }
    }
}

