__global__ void Kernel_Softmax_seg(float *dev_x, const int c, const int size) {
    unsigned int i = blockDim.x * blockIdx.x + threadIdx.x;
    int N = size;

    while (i < N) {
        float temp = 0.0;

        // Find max value
        for (int j = 0; j < c; j++) {
            temp = fmaxf(dev_x[j * size + i], temp);
        }

        // Subtract max and exponentiate
        for (int j = 0; j < c; j++) {
            dev_x[j * size + i] = expf(dev_x[j * size + i] - temp);
        }

        // Sum of exponentials
        temp = 0.0;
        for (int j = 0; j < c; j++) {
            temp += dev_x[j * size + i];
        }

        // Normalize
        for (int j = 0; j < c; j++) {
            dev_x[j * size + i] /= temp;
        }

        i += gridDim.x * blockDim.x;
    }
}

__global__ void pad_input(float *f_in, float *f_out, int H, int W, int D, int pad) {
