    int dep = blockIdx.z * blockDim.z + threadIdx.z;

    int new_H = H + 2 * pad;
    int new_W = W + 2 * pad;

    int i = dep * new_H * new_W + col * new_W + row;
    int j = dep * H * W + (col - pad) * W + (row - pad);

    if (col < new_H && row < new_W && dep < D) {
        if ((col < pad || col > H + pad - 1) || (row < pad || row > W + pad - 1)) {
            f_out[i] = 0;
