__global__ void cudaRunComplexFilter(float *I, float *Q, int samplesLength, float *hr, float *hi, int filterLength, float *filtered_I, float *filtered_Q, int convLength) {
    int sampleIndex = (blockIdx.x * blockDim.x) + threadIdx.x;

    if (sampleIndex >= convLength)
        return;

    int index;
    float sumI, sumQ;

    sumI = 0;
    sumQ = 0;

    for (int j = sampleIndex - filterLength + 1; j <= sampleIndex; j++) {
        index = sampleIndex - j;

        if ((j < samplesLength) && (j >= 0)) {
            sumI += (I[j] * hr[index]) - (Q[j] * hi[index]);
            sumQ += (I[j] * hi[index]) + (Q[j] * hr[index]);
        }
    }

    filtered_I[sampleIndex] = sumI;
    filtered_Q[sampleIndex] = sumQ;
}

__global__ void opL21(float *vec, float *vec1, long depth, long rows, long cols) {
    unsigned long x = threadIdx.x + blockIdx.x * blockDim.x;
    unsigned long y = threadIdx.y + blockIdx.y * blockDim.y;
    unsigned long z = threadIdx.z + blockIdx.z * blockDim.z;
    unsigned long long i = z * rows * cols + y * cols + x;
    unsigned long long j = z * rows * cols + x;
    unsigned long size2d = cols;
    unsigned long size3d = depth * rows * cols + rows * cols + cols;

    if (x >= cols || y >= rows || z >= depth)
        return;

    if (i + cols + 1 >= size3d)
        return;

    vec[i + cols] = 0.25 * (vec1[i + 1] + vec1[i] + vec1[i + cols + 1] + vec1[i + cols]);

    if (j + 1 >= size2d)
        return;

    vec[j] = (vec1[j] + vec1[j + 1]) / 4;
}

__global__ void reorg_kernel(int N, float *x, int w, int h, int c, int batch, int stride, int forward, float *out) {
    int i = (blockIdx.x + blockIdx.y * gridDim.x) * blockDim.x + threadIdx.x;

    if (i >= N)
        return;

    int in_index = i;
    int in_w = i % w;
    i = i / w;
    int in_h = i % h;
    i = i / h;
    int in_c = i % c;
    i = i / c;
    int b = i % batch;

    int out_c = c / (stride * stride);
    int c2 = in_c % out_c;
    int offset = in_c / out_c;
    int w2 = in_w * stride + offset % stride;
    int h2 = in_h * stride + offset / stride;

    int out_index = w2 + w * stride * (h2 + h * stride * (c2 + out_c * b));

    if (forward)
        out[out_index] = x[in_index];
    else
        out[in_index] = x[out_index];
}

