	int dist=(loc_max+1)/2;
	j=threadIdx.y*blockDim.x+threadIdx.x;
	__syncthreads();
	while(loc_max>1){
		if((j<dist)&&((j+dist)<loc_max)){frc3[j]+=frc3[j+dist];}
		loc_max=dist;
		dist=(dist+1)/2;
