__global__ static void pintgr_gpu_kernel_4(double* frc,
		const int num){
	int i, loc_max, dist;

	double* buffer = (double*)extern_share_data;

	i=threadIdx.x;

	buffer[i]=0.0;
	while(i<num){
		buffer[threadIdx.x]+=frc[i];
