	if(i1>=n1){return;}

	u[i3*n2*n1+0*n1+i1]=u[i3*n2*n1+(n2-2)*n1+i1];
	u[i3*n2*n1+(n2-1)*n1+i1]=u[i3*n2*n1+1*n1+i1];
}

__global__ void comm3_gpu_kernel_3(double* u,
		int n1, 
		int n2, 
